<?php $this->layout('default'); use Moves\Services\CmsContent as C; use Moves\Support\CmsView as V; $q = V::queryString('q'); $result = C::helpListing(['q' => $q], V::queryPage()); $folders = C::helpFolders(); $tab = V::queryString('aba');
$this->start('actions'); ?><a class="cms-btn-primary" href="/conteudos/novo?type=help"><?= V::icon('plus') ?>Nova matéria</a><?php $this->stop(); ?>
<?= V::tabs([['/base-de-conhecimento', 'Matérias', $result['total'], $tab === ''], ['?aba=pastas', 'Pastas', count($folders), $tab === 'pastas']], 'Base de conhecimento') ?>
<?php if ($tab === 'pastas'): ?><div class="cms-form-list"><form class="cms-card" method="post" action="/acao/category-save"><header class="cms-card-head"><div><h2>Nova pasta</h2><small>Agrupe as matérias por assunto.</small></div><?= V::icon('list') ?></header><?= V::csrf() ?><input type="hidden" name="type" value="help"><?= V::field('Nome', 'title', '', ['required' => true]) ?><?= V::field('Descrição', 'description', '', ['type' => 'textarea', 'rows' => 3]) ?><div class="cms-form-end"><button class="cms-btn-primary">Salvar pasta</button></div></form><section class="cms-card"><header class="cms-card-head"><h2>Pastas</h2><b class="cms-count"><?= count($folders) ?></b></header><?php if ($folders === []): ?><?= V::empty('Nenhuma pasta cadastrada.') ?><?php endif; foreach ($folders as $f): ?><div class="cms-row"><div><strong><?= V::e($f['title']) ?></strong><br><small><?= (int) $f['posts_count'] ?> matéria(s)</small></div><?= V::iconAction('category-delete', 'Excluir', ['id' => $f['id']], 'Excluir esta pasta?') ?></div><?php endforeach; ?></section></div>
<?php else: ?><section class="cms-list"><?= V::listHead('Conteúdo cadastrado', $result['total'] . ' matéria(s)', V::searchForm('Buscar matéria')) ?><?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma matéria cadastrada.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Título</th><th>Pasta</th><th>Status</th><th class="num">Visualizações</th><th class="num">Avaliação</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($result['rows'] as $a): ?><tr><td><a href="/conteudos/<?= (int) $a['id'] ?>"><?= V::e($a['title']) ?></a></td><td><?= V::e($a['folder'] ?? '—') ?></td><td><?= V::badge($a['status'], $a['status'] === 'published' ? 'Publicada' : 'Rascunho') ?></td><td class="num"><?= (int) $a['views'] ?></td><td class="num"><?= (int) $a['votes'] > 0 ? round((int) $a['helpful'] / (int) $a['votes'] * 100) . '% úteis (' . (int) $a['votes'] . ')' : '—' ?></td><td class="cms-td-actions"><?= V::iconLink('/conteudos/' . (int) $a['id'], 'Editar') ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></section><?php endif; ?>
